parameters.jsCode:
const attendees = $input.first().json.attendees || [];
const external = attendees.filter(a => !a.email.endsWith('@mycompany.com'));
if (external.length === 0) return [];

const guest = external[0];
const domain = guest.email.split('@').pop();
return [{
  json: {
    guest_email: guest.email,
    guest_name: guest.displayName || guest.email.split('@')[0],
    domain: domain,
    summary: $input.first().json.summary,
    start_time: $input.first().json.start?.dateTime
  }
}];

